* ESDS -- shared map for ESDR (REXX) and ESDC (COBOL) sample
* programs that walk a tmp_dir sequential file via STARTBR /
* READNEXT / READPREV / ENDBR. The bricks-flavoured RBA is decimal
* text (see PROGRAMMING.md Chapter 8a); each ROWn carries one
* record pre-formatted by the host program as the 10-character
* zero-padded RBA, two spaces, then up to 64 bytes of record text.
* TYPE shows the source language ("REXX" or "COBOL") so an operator
* who hits both samples back-to-back can tell which one is on screen.
* INFOLINE carries the status banner (RESP name, LENGERR notice,
* "TOP/BOT", etc.) and goes red on error states.
MAP ESDS SIZE 24x80
  FIELD INFOLINE AT 0,0   LEN 78 PROT BRIGHT COLOR=WHITE
  FIELD AT 2,2   LEN 50 PROT BRIGHT COLOR=BLUE     "ESDS Browse Demo"
  FIELD TYPE     AT 2,60  LEN 18 PROT BRIGHT COLOR=YELLOW
  FIELD AT 4,2   LEN 78 PROT DIM    COLOR=TURQUOISE "RBA         RECORD"
  FIELD ROW1   AT 5,2   LEN 76 PROT COLOR=GREEN
  FIELD ROW2   AT 6,2   LEN 76 PROT COLOR=GREEN
  FIELD ROW3   AT 7,2   LEN 76 PROT COLOR=GREEN
  FIELD ROW4   AT 8,2   LEN 76 PROT COLOR=GREEN
  FIELD ROW5   AT 9,2   LEN 76 PROT COLOR=GREEN
  FIELD ROW6   AT 10,2  LEN 76 PROT COLOR=GREEN
  FIELD ROW7   AT 11,2  LEN 76 PROT COLOR=GREEN
  FIELD ROW8   AT 12,2  LEN 76 PROT COLOR=GREEN
  FIELD ROW9   AT 13,2  LEN 76 PROT COLOR=GREEN
  FIELD ROW10  AT 14,2  LEN 76 PROT COLOR=GREEN
  FIELD ROW11  AT 15,2  LEN 76 PROT COLOR=GREEN
  FIELD ROW12  AT 16,2  LEN 76 PROT COLOR=GREEN
  FIELD ROW13  AT 17,2  LEN 76 PROT COLOR=GREEN
  FIELD ROW14  AT 18,2  LEN 76 PROT COLOR=GREEN
  FIELD ROW15  AT 19,2  LEN 76 PROT COLOR=GREEN
  FIELD AT 22,2  LEN 76 PROT DIM COLOR=BLUE   "PF7=PageUp  PF8=PageDown  PF3=Exit"
ENDMAP
